import{t as e}from"./types-DccqHlFD.js";var t=`A chain sprocket is a toothed wheel that works together with a chain to transfer mechanical power from one rotating shaft to another.`,n=[`Provide positive power transmission with little slip under normal operating conditions.`,`Can transfer power between shafts separated by a distance.`,`Suitable for many industrial loads.`,`Allow speed changes by using different sprocket sizes.`,`Can be maintained by inspecting and lubricating the chain as required.`],r=[e({name:`Chain Sprocket`,category:`Sprockets`,subtitle:`Chain Sprocket`,description:t,features:n,specs:{Type:`Chain Sprocket`},imagePath:`/products/chain-sprocket/chain-sprocket.webp`,galleryImages:[`/chain-sprocket/support/20200620_105558.jpg`,`/chain-sprocket/support/20200919_121502.jpg`,`/chain-sprocket/support/20220217_113750.jpg`,`/chain-sprocket/support/20220804_095107.jpg`]})],i={path:`/chain-sprocket`,title:`Chain Sprocket`,description:t,productGroups:[{products:r,photos:[`/chain-sprocket/support/20200620_105558.jpg`,`/chain-sprocket/support/20200919_121502.jpg`,`/chain-sprocket/support/20220217_113750.jpg`,`/chain-sprocket/support/20220804_095107.jpg`,`/chain-sprocket/support/20230505_151928.jpg`,`/chain-sprocket/support/20250320_113320.jpg`,`/chain-sprocket/support/20251215_164115.jpg`]}],sections:[{kind:`text`,paragraphs:[`In simple words, the sprocket teeth engage with the chain links, allowing the motor's rotation to drive another machine or component.`,`Chain sprockets are commonly used in industrial machinery, conveyors, motorcycles, bicycles, and material-handling equipment.`]},{kind:`groups`,eyebrow:`Main parts of a chain sprocket system`,groups:[{title:`Sprocket`,items:[`A toothed wheel that engages with the chain and transfers rotational movement.`]},{title:`Chain`,items:[`A series of connected metal links that engages with the sprocket teeth to transmit power.`]},{title:`Driving and driven sprockets`,items:[`The driving sprocket receives power from the motor or gearbox. The driven sprocket transfers that movement to the connected machine.`]}],paragraphs:[`For example, an electric motor rotates a small sprocket. The chain transfers the movement to a larger sprocket connected to a conveyor.`,`A larger driven sprocket generally produces lower speed and higher torque.`,`A smaller driven sprocket generally produces higher speed and lower torque.`,`These effects assume the same chain speed and ideal transmission, before losses.`]},{kind:`list`,eyebrow:`Applications of chain sprockets`,items:[`Conveyor systems: Move products, boxes, and bulk materials.`,`Industrial machinery: Transfer power between rotating shafts.`,`Packaging machines: Drive moving parts and production lines.`,`Agricultural equipment: Drive chains in harvesters and other farm machinery.`,`Motorcycles and bicycles: Transfer driving power to the wheels.`,`Agitators and mixers: Drive a shaft through a chain transmission when the machine design uses this arrangement.`]},{kind:`list`,eyebrow:`Advantages of chain sprockets`,items:n},{kind:`groups`,eyebrow:`Applications of Chain Sprockets`,intro:[`A chain sprocket is a toothed wheel that works with a chain to transmit power and rotational movement from one shaft to another. It is commonly used in industrial machinery, conveyor systems, vehicles, and agricultural equipment.`],subheading:`Common industrial applications`,groups:[{title:`Conveyor systems`,items:[`Move products and materials along production lines.`,`Drive conveyor chains and rollers.`,`Transport boxes, pallets, and heavy materials.`]},{title:`Industrial machinery`,items:[`Transfer power from a motor or gearbox to another shaft.`,`Drive rotating machine components.`,`Maintain a fixed speed relationship between connected sprockets.`]},{title:`Packaging machines`,items:[`Drive bottle and carton conveyors.`,`Synchronize machine movements.`,`Move products between packaging stations.`]},{title:`Agricultural equipment`,items:[`Drive harvesting mechanisms.`,`Transfer power to feeding and conveying systems.`,`Operate chain-driven farm machinery.`]},{title:`Motorcycles and bicycles`,items:[`Transfer power from the engine or pedals to the rear wheel.`,`Change the speed and torque relationship using different sprocket sizes.`]},{title:`Water and wastewater treatment`,items:[`Drive chain-operated sludge scrapers.`,`Move mechanical skimmers inside treatment tanks.`,`Operate chain-driven material-handling equipment.`]},{title:`Agitators and mixers`,items:[`Transfer rotation from a motor to a mixing shaft.`,`Adjust the mixing speed using different sprocket sizes.`,`Drive mixing equipment when a chain transmission is suitable for the design.`]}]}]};export{r as n,i as t};